type Session struct { conn net.Conn; once sync.Once }

func (s *Session) Close() error {            // idempotent, cascades to owned conn
    var err error
    s.once.Do(func() { err = s.conn.Close() })
    return err
}
func run(addr string) error {
    s, err := dial(addr); if err != nil { return err }
    defer s.Close()                          // runs on every return path, LIFO
    return s.roundTrip()
}
